import{_ as t,o as s,c as r,ah as a}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse(`{"title":"Structure de l'établissement","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/structure-etablissement.md","filePath":"src/guide/admin/structure-etablissement.md"}`),n={name:"guide/admin/structure-etablissement.md"};function i(o,e,l,d,u,c){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="structure-de-l-etablissement" tabindex="-1">Structure de l&#39;établissement <a class="header-anchor" href="#structure-de-l-etablissement" aria-label="Permalink to &quot;Structure de l&#39;établissement&quot;">​</a></h1><p>Cette section regroupe toute la configuration de base d&#39;ERA : c&#39;est ce que vous mettez en place en début d&#39;année, avant que le personnel et les élèves puissent commencer à travailler dans l&#39;app. L&#39;ordre logique est généralement : année scolaire → sites → départements → classes → matières → matières par département → types d&#39;évaluation → périodes scolaires → compétences (si besoin).</p><h2 id="annees-scolaires" tabindex="-1">Années scolaires <a class="header-anchor" href="#annees-scolaires" aria-label="Permalink to &quot;Années scolaires&quot;">​</a></h2><p><strong>Paramétrage scolaire → Années scolaires</strong> liste les années scolaires de votre établissement, avec le nombre de classes de chacune. Une seule année est « En cours » à la fois — c&#39;est celle qui apparaît par défaut dans le tableau de bord et sur les nouveaux formulaires.</p><p>Pour créer une année scolaire :</p><ol><li>Cliquez sur <strong>Nouvelle année scolaire</strong>.</li><li>Renseignez les champs ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Libellé</td><td>ex. « 2025-2026 »</td></tr><tr><td>Date de début</td><td>—</td></tr><tr><td>Date de fin</td><td>—</td></tr></tbody></table><p>Depuis la liste, le bouton <strong>Définir comme actuelle</strong> bascule l&#39;année en cours. Supprimer une année scolaire est définitif et irréversible.</p><h3 id="cloturer-une-annee-ou-une-periode" tabindex="-1">Clôturer une année ou une période <a class="header-anchor" href="#cloturer-une-annee-ou-une-periode" aria-label="Permalink to &quot;Clôturer une année ou une période&quot;">​</a></h3><p>Une fois l&#39;année ou le trimestre terminé, clôturez-le pour éviter les saisies par inadvertance : un enseignant qui rouvre un vieux lien ne modifiera plus les notes d&#39;un trimestre déjà remis aux familles.</p><p>La colonne <strong>État</strong> de <strong>Années scolaires</strong> et de <strong>Périodes scolaires</strong> porte les actions :</p><ul><li><strong>Clôturer</strong> — disponible une fois la date de fin passée. Les notes, présences, bulletins, cahiers de textes, observations de compétences et incidents de la période passent en lecture seule, pour tout le monde. Les écrans concernés affichent un message et leur bouton <strong>Enregistrer</strong> est désactivé.</li><li><strong>Rouvrir</strong> — pour une correction ponctuelle. Vous indiquez un motif et une durée (48 heures par défaut, une semaine au maximum) : la période se referme toute seule à l&#39;échéance, personne n&#39;a à y penser. Le motif et l&#39;auteur sont enregistrés dans le <a href="/guide/admin/demo-et-journal.html">journal d&#39;activité</a>.</li><li><strong>Annuler la clôture</strong> — si la clôture a été faite par erreur. La période redevient modifiable sans limite de temps.</li></ul><p>Clôturer une année clôt tout ce qu&#39;elle contient, y compris les jours situés entre deux trimestres (vacances, rattrapages). Une période rouverte reste modifiable même si son année est close.</p><div class="tip custom-block"><p class="custom-block-title">La caisse n&#39;est jamais gelée</p><p>La clôture ne concerne que le pédagogique. Les paiements, les remises et les dépenses restent possibles sur une année close : un établissement encaisse presque toujours des arriérés après la fin des cours.</p></div><h2 id="sites" tabindex="-1">Sites <a class="header-anchor" href="#sites" aria-label="Permalink to &quot;Sites&quot;">​</a></h2><p>Si votre établissement a plusieurs campus, <strong>Paramétrage scolaire → Sites</strong> vous permet de les gérer. Un site a deux champs : <strong>Nom</strong> et <strong>Adresse</strong>. Chaque département, classe, grille de frais et employé est ensuite rattaché à un site — si vous n&#39;avez qu&#39;un seul campus, créez un unique site et rattachez-y tout le reste.</p><p>Pour créer un site : allez dans <strong>Paramétrage scolaire → Sites</strong>, cliquez sur <strong>Nouveau site</strong>, renseignez le nom (et l&#39;adresse, facultative), puis <strong>Enregistrer</strong>.</p><h3 id="logo-du-site" tabindex="-1">Logo du site <a class="header-anchor" href="#logo-du-site" aria-label="Permalink to &quot;Logo du site&quot;">​</a></h3><p>Une fois le site créé, sa page <strong>Modifier</strong> propose un <strong>logo du site</strong>, sous le formulaire nom/adresse. Ce logo s&#39;imprime, à la place du logo de l&#39;établissement, sur :</p><ul><li>les <strong>bulletins</strong> des classes rattachées à ce site ;</li><li>les <strong>reçus de paiement</strong> des élèves inscrits dans une classe de ce site.</li></ul><p>Les sites qui n&#39;ont pas de logo propre continuent d&#39;utiliser celui des <a href="/guide/admin/parametres-application.html">paramètres de l&#39;application</a> — vous n&#39;avez donc rien à faire si tous vos campus partagent la même identité.</p><p>Seul le logo change : le menu et la page d&#39;accueil publique gardent le logo de l&#39;établissement, et l&#39;adresse, le téléphone et l&#39;e-mail imprimés sur les reçus restent ceux des paramètres de l&#39;application.</p><p>Formats acceptés : PNG, JPG, WebP ou SVG, 2 Mo maximum. Le bouton <strong>Retirer</strong> supprime le logo du site et ramène celui de l&#39;établissement. Les bulletins et reçus déjà générés ne sont pas réécrits : le changement s&#39;applique aux documents produits ensuite.</p><h2 id="departements" tabindex="-1">Départements <a class="header-anchor" href="#departements" aria-label="Permalink to &quot;Départements&quot;">​</a></h2><p>Un département correspond à un niveau ou une filière (ex. « Maternelle », « Collège », « Terminale BI »). <strong>Paramétrage scolaire → Départements</strong> liste les départements de l&#39;établissement avec les sites où chacun est actif.</p><p>Pour créer un département :</p><ol><li>Cliquez sur <strong>Nouveau département</strong>.</li><li>Renseignez les champs ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Nom</td><td>—</td></tr><tr><td>Type</td><td>Crèche, Maternelle, Élémentaire, Collège, Lycée, BI ou Université</td></tr><tr><td>Référentiel</td><td>Français ou Togolais — détermine les règles de notation appliquées à ce département</td></tr><tr><td>Disponible sur</td><td>cochez un ou plusieurs sites où ce département est actif</td></tr></tbody></table><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes&quot;">​</a></h2><p><strong>Paramétrage scolaire → Classes</strong> liste les classes, avec des filtres par site, département et année scolaire, et le nombre d&#39;élèves inscrits (sur l&#39;effectif maximum si vous en avez défini un).</p><p>Pour créer une classe :</p><ol><li>Cliquez sur <strong>Nouvelle classe</strong>.</li><li>Renseignez les champs de la section « Structure » ci-dessous.</li><li>Renseignez, si besoin, les champs de la section « Options » ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Section « Structure » :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Nom</td><td>—</td></tr><tr><td>Site</td><td>—</td></tr><tr><td>Département</td><td>—</td></tr><tr><td>Année scolaire</td><td>—</td></tr></tbody></table><p>Section « Options » (facultatifs) :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Effectif</td><td>limite de places ; laissez vide pour « Pas de limite »</td></tr><tr><td>Professeur principal</td><td>choisi parmi les enseignants existants</td></tr><tr><td>Modèle de bulletin</td><td>Classique, Compact ou Traditionnel (à la française) ; laissez vide pour utiliser le modèle par défaut de l&#39;établissement</td></tr></tbody></table><p>Depuis la liste des classes, chaque ligne propose aussi des accès rapides vers <strong>Emploi du temps</strong> et <strong>Bulletins</strong> de cette classe (voir les guides dédiés) — pas besoin de repasser par le menu.</p><h2 id="matieres" tabindex="-1">Matières <a class="header-anchor" href="#matieres" aria-label="Permalink to &quot;Matières&quot;">​</a></h2><p><strong>Paramétrage scolaire → Matières</strong> est le catalogue global des matières de l&#39;établissement (ex. « Mathématiques », « Anglais »). Une matière n&#39;a qu&#39;un nom ; c&#39;est son rattachement à un département (voir ci-dessous) qui définit son coefficient et son barème.</p><p>Pour créer une matière : <strong>Paramétrage scolaire → Matières</strong>, <strong>Nouvelle matière</strong>, renseignez le nom, <strong>Enregistrer</strong>.</p><h2 id="matieres-par-departement" tabindex="-1">Matières par département <a class="header-anchor" href="#matieres-par-departement" aria-label="Permalink to &quot;Matières par département&quot;">​</a></h2><p><strong>Paramétrage scolaire → Matières par département</strong> rattache une matière du catalogue à un département, avec les règles de notation propres à ce département.</p><p>Pour créer un rattachement :</p><ol><li>Cliquez sur <strong>Nouvelle affectation</strong>.</li><li>Renseignez les champs ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Département</td><td>—</td></tr><tr><td>Matière</td><td>—</td></tr><tr><td>Coefficient</td><td>—</td></tr><tr><td>Barème</td><td>note maximale possible ; 20 par défaut</td></tr><tr><td>Matière de spécialité (choisie par élève)</td><td>cochez si cette matière n&#39;est pas suivie par tous les élèves du département mais choisie individuellement (voir <a href="/guide/admin/eleves-tuteurs.html">Élèves et tuteurs</a>) ; laissez décoché pour une matière de tronc commun, appliquée automatiquement à tous</td></tr></tbody></table><h2 id="types-d-evaluation" tabindex="-1">Types d&#39;évaluation <a class="header-anchor" href="#types-d-evaluation" aria-label="Permalink to &quot;Types d&#39;évaluation&quot;">​</a></h2><p><strong>Paramétrage scolaire → Types d&#39;évaluation</strong> définit les catégories d&#39;évaluation utilisées par les enseignants (devoir, composition, interrogation...) et le poids de chacune dans le calcul de la moyenne d&#39;une matière.</p><p>Pour créer un type : <strong>Paramétrage scolaire → Types d&#39;évaluation</strong>, <strong>Nouveau type d&#39;évaluation</strong>, renseignez le <strong>Nom</strong> et le <strong>Poids</strong> (ex. 1 pour un devoir, 2 pour une composition), <strong>Enregistrer</strong>.</p><h2 id="periodes-scolaires" tabindex="-1">Périodes scolaires <a class="header-anchor" href="#periodes-scolaires" aria-label="Permalink to &quot;Périodes scolaires&quot;">​</a></h2><p><strong>Paramétrage scolaire → Périodes scolaires</strong> définit les périodes de notation (trimestres, semestres...) d&#39;une année scolaire — elles servent à la fois à la saisie des notes par les enseignants et à la publication des bulletins.</p><p>Pour créer une période :</p><ol><li>Cliquez sur <strong>Nouvelle période</strong>.</li><li>Renseignez les champs ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Année scolaire</td><td>—</td></tr><tr><td>Nom</td><td>ex. « Trimestre 1 »</td></tr><tr><td>Date de début</td><td>—</td></tr><tr><td>Date de fin</td><td>—</td></tr><tr><td>Ordre</td><td>position de cette période parmi les autres de la même année</td></tr></tbody></table><h2 id="competences" tabindex="-1">Compétences <a class="header-anchor" href="#competences" aria-label="Permalink to &quot;Compétences&quot;">​</a></h2><p><strong>Paramétrage scolaire → Compétences</strong> ne concerne que les départements qualitatifs (crèche, maternelle) : au lieu de notes chiffrées, les enseignants y observent des compétences (ex. « Reconnaît les couleurs »).</p><p>Pour créer une compétence : <strong>Paramétrage scolaire → Compétences</strong>, <strong>Nouvelle compétence</strong>, choisissez le <strong>Département</strong> qualitatif concerné, renseignez le <strong>Nom</strong>, <strong>Enregistrer</strong>.</p>',56)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
